package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.workflow.PlanDraftProtocol;
import com.ruoyi.medical.workflow.PlanDraftDelivery;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
/** Immutable original start/attempt/acceptance ledger. A start attempt is committed before
 * any Temporal I/O; after uncertainty only query recovery is permitted. */
public final class TaskPlanDraftLaunchLedger {
    private final JdbcTemplate db;private final TaskPlanDraftJobs jobs;private final TaskPlanDraftSchema schema;
    public TaskPlanDraftLaunchLedger(DataSource data,TaskPlanDraftJobs jobs,TaskPlanDraftSchema schema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.jobs=jobs;this.schema=schema;}
    final class Intent {
        private final TaskPlanDraftJobs.Job job;private final String command,referenceHash,configurationHash;
        private final PlanDraftProtocol.Reference reference;private final TaskPlanDraftLaunchConfiguration configuration;
        private Intent(TaskPlanDraftJobs.Job job,String command,PlanDraftProtocol.Reference reference,String referenceHash,TaskPlanDraftLaunchConfiguration configuration,String configurationHash){this.job=job;this.command=command;this.reference=reference;this.referenceHash=referenceHash;this.configuration=configuration;this.configurationHash=configurationHash;}
        TaskPlanDraftJobs.Job job(){return job;}String commandId(){return command;}PlanDraftProtocol.Reference reference(){return reference;}String referenceHash(){return referenceHash;}
    }
    Intent prepare(TaskPlanDraftJobAuthority.Verified authority,TaskPlanDraftObjectRegistration.Registered input,TaskPlanDraftLaunchConfiguration configuration)throws Exception {
        authority.requireUnchanged();input.requireUnchanged();var j=authority.job();if(!j.equals(input.job())||!j.inputHash().equals(input.reference().sha256()))bad();
        var limits=authority.current().releaseManifest().limits();
        if(configuration.activityTimeoutMillis()>Math.multiplyExact((long)limits.maxWallTimeSeconds(),1000L)||configuration.heartbeatTimeoutMillis()>Math.multiplyExact((long)limits.heartbeatTimeoutSeconds(),1000L))deny();
        var admitted=schema.read(j.admissionJson());var reference=new PlanDraftProtocol.Reference("1.0.0","SYSTEM_JOB","PLAN_DRAFT","N01",j.tenant(),j.project(),j.run(),j.step(),j.task(),j.taskRevision(),input.artifactId(),j.inputHash(),input.receiptSha256(),schema.hash(admitted),text(admitted.required("execution_policy"),"version_id"),configuration.controlTaskQueue(),configuration.professionalTaskQueue(),configuration.activityTimeoutMillis(),configuration.heartbeatTimeoutMillis());
        var existing=db.queryForList("SELECT * FROM task_plan_draft_launch_intent WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",j.tenant(),j.run());
        if(!existing.isEmpty()){var original=read(j,one(existing));if(!reference.equals(original.reference)||!configuration.equals(original.configuration))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return original;}
        var status=one(db.query("SELECT status FROM system_job_run WHERE tenant_id=? AND run_id=? AND job_type='PLAN_DRAFT' AND workflow_id IS NULL AND started_at IS NULL AND ended_at IS NULL LIMIT 2 FOR UPDATE",(r,n)->r.getString(1),j.tenant(),j.run()));if(!"QUEUED".equals(status))deny();
        String command=UUID.randomUUID().toString(),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var now=now();String hash=schema.hash(reference),configHash=schema.hash(configuration);
        var receipt=evidence(command,hash,configHash,reference);journal(j,audit,event,"task.plan_draft.launch.prepared",command,receipt,now);
        changed(db.update("INSERT INTO task_plan_draft_launch_intent(tenant_id,project_id,run_id,command_id,canonical_reference,reference_sha256,input_artifact_id,input_receipt_sha256,job_admission_sha256,config_json,config_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",j.tenant(),j.project(),j.run(),command,schema.canonical(reference),hash,input.artifactId(),input.receiptSha256(),schema.hash(admitted),schema.canonical(configuration),configHash,audit,event,schema.manifest(),j.actor(),now,j.classification()));
        authority.requireUnchanged();return read(j,one(db.queryForList("SELECT * FROM task_plan_draft_launch_intent WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",j.tenant(),j.run())));
    }
    static final class Attempt {
        private final Intent intent;private final boolean recoveryOnly;
        private Attempt(Intent intent,boolean recoveryOnly){this.intent=intent;this.recoveryOnly=recoveryOnly;}
        Intent intent(){return intent;}boolean recoveryOnly(){return recoveryOnly;}
    }
    Attempt attempt(TaskPlanDraftJobAuthority.Verified authority,Intent intended)throws Exception {
        require(authority,intended);var j=intended.job;var rows=db.queryForList("SELECT * FROM task_plan_draft_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",j.tenant(),j.run());
        if(!rows.isEmpty()){verifyAttempt(intended,one(rows));return new Attempt(intended,true);}
        changed(db.update("INSERT INTO task_plan_draft_launch_attempt(tenant_id,project_id,run_id,command_id,reference_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,'1.0.0',?,?,?,?)",j.tenant(),j.project(),j.run(),intended.command,intended.referenceHash,schema.manifest(),j.actor(),now(),j.classification()));
        verifyAttempt(intended,one(db.queryForList("SELECT * FROM task_plan_draft_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2",j.tenant(),j.run())));authority.requireUnchanged();return new Attempt(intended,false);
    }
    void require(TaskPlanDraftJobAuthority.Verified authority,Intent intended)throws Exception {authority.requireUnchanged();var j=authority.job();if(!j.equals(intended.job))bad();var actual=read(j,one(db.queryForList("SELECT * FROM task_plan_draft_launch_intent WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",j.tenant(),j.run())));if(!actual.command.equals(intended.command)||!actual.reference.equals(intended.reference)||!actual.configuration.equals(intended.configuration))bad();}
    boolean attempted(String tenant,String run){if(!TransactionSynchronizationManager.isActualTransactionActive()||!tenant.equals(TenantScope.requireCurrent().tenantId()))deny();var rows=db.query("SELECT reference_sha256 FROM task_plan_draft_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2",(r,n)->r.getString(1),tenant,run);if(rows.size()>1)bad();return !rows.isEmpty();}
    Intent recoveryOriginal(String tenant,String run)throws Exception {var j=jobs.byRun(tenant,run);if(!j.actor().equals(TenantScope.requireCurrent().subjectId()))deny();var intent=read(j,one(db.queryForList("SELECT * FROM task_plan_draft_launch_intent WHERE tenant_id=? AND run_id=? LIMIT 2",tenant,run)));verifyAttempt(intent,one(db.queryForList("SELECT * FROM task_plan_draft_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2",tenant,run)));return intent;}
    Accepted accepted(Intent intended,PlanDraftDelivery.Accepted received)throws Exception {
        var intent=recoveryOriginal(intended.job.tenant(),intended.job.run());var j=intent.job;
        if(!received.reference().equals(intent.reference)||!received.commandId().equals(intent.command)||!intended.reference.equals(intent.reference))bad();
        var receipt=evidence(intent.command,intent.referenceHash,intent.configurationHash,intent.reference).put("workflow_id",intent.reference.workflowId()).put("temporal_run_id",received.temporalRunId());
        var rows=db.queryForList("SELECT * FROM task_plan_draft_launch_receipt WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",j.tenant(),j.run());
        if(!rows.isEmpty()){verifyReceipt(intent,receipt,one(rows));return new Accepted(receipt,null);}
        var beforeRevision=one(db.query("SELECT revision FROM system_job_run WHERE tenant_id=? AND run_id=? AND status='QUEUED' AND workflow_id IS NULL AND started_at IS NULL AND ended_at IS NULL LIMIT 2 FOR UPDATE",(r,n)->new java.math.BigInteger(r.getString(1)),j.tenant(),j.run()));
        String audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var now=now();
        journal(j,audit,event,"task.plan_draft.launch.accepted",intent.command,receipt,now);
        changed(db.update("INSERT INTO task_plan_draft_launch_receipt(tenant_id,project_id,run_id,workflow_id,temporal_run_id,reference_sha256,receipt_json,receipt_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",j.tenant(),j.project(),j.run(),intent.reference.workflowId(),received.temporalRunId(),intent.referenceHash,schema.canonical(receipt),schema.hash(receipt),audit,event,schema.manifest(),j.actor(),now,j.classification()));
        // Actual acceptance is the sole QUEUED->RUNNING transition. Never reopen a terminal job.
        changed(db.update("UPDATE system_job_run SET workflow_id=?,status='RUNNING',started_at=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND run_id=? AND job_type='PLAN_DRAFT' AND execution_kind='SYSTEM_JOB' AND input_sha256=? AND status='QUEUED' AND revision=? AND workflow_id IS NULL AND started_at IS NULL AND ended_at IS NULL",intent.reference.workflowId(),now,now,j.tenant(),j.project(),j.run(),j.inputHash(),beforeRevision));
        verifyReceipt(intent,receipt,one(db.queryForList("SELECT * FROM task_plan_draft_launch_receipt WHERE tenant_id=? AND run_id=? LIMIT 2",j.tenant(),j.run())));return new Accepted(receipt,new LaunchTransition(intent,received,receipt,beforeRevision));
    }
    static final class Accepted {
        private final JsonNode receipt;private final LaunchTransition transition;
        private Accepted(JsonNode receipt,LaunchTransition transition){this.receipt=receipt.deepCopy();this.transition=transition;}
        JsonNode receipt(){return receipt.deepCopy();}LaunchTransition transition(){return transition;}
    }
    public final class LaunchTransition {
        private final Intent intent;private final PlanDraftDelivery.Accepted accepted;private final JsonNode receipt;private final java.math.BigInteger before,after;
        private final Thread thread=Thread.currentThread();private final TenantScope scope=TenantScope.requireCurrent();private final Map<Object,Object> resources=Map.copyOf(TransactionSynchronizationManager.getResourceMap());
        private LaunchTransition(Intent intent,PlanDraftDelivery.Accepted accepted,JsonNode receipt,java.math.BigInteger before){this.intent=intent;this.accepted=accepted;this.receipt=receipt.deepCopy();this.before=before;this.after=before.add(java.math.BigInteger.ONE);if(resources.isEmpty())deny();}
        public java.math.BigInteger beforeRevision(){return before;}public java.math.BigInteger afterRevision(){return after;}
        public void requireFor(String tenant,String actor,String run,String principal,java.math.BigInteger expectedBefore,java.math.BigInteger expectedAfter)throws Exception {
            if(thread!=Thread.currentThread()||scope!=TenantScope.requireCurrent()||!TransactionSynchronizationManager.isActualTransactionActive())deny();var current=TransactionSynchronizationManager.getResourceMap();if(current.size()!=resources.size()||resources.entrySet().stream().anyMatch(e->current.get(e.getKey())!=e.getValue()))deny();
            var j=intent.job;if(!tenant.equals(j.tenant())||!actor.equals(j.actor())||!run.equals(j.run())||!principal.equals(j.principal())||!before.equals(expectedBefore)||!after.equals(expectedAfter)||!accepted.reference().equals(intent.reference)||!accepted.commandId().equals(intent.command))bad();
            verifyReceipt(intent,receipt,one(db.queryForList("SELECT * FROM task_plan_draft_launch_receipt WHERE tenant_id=? AND run_id=? LIMIT 2",tenant,run)));
            if(one(db.query("SELECT COUNT(*) FROM system_job_run WHERE tenant_id=? AND run_id=? AND status='RUNNING' AND revision=? AND workflow_id=? AND input_sha256=? AND ended_at IS NULL",(r,n)->r.getInt(1),tenant,run,after,intent.reference.workflowId(),j.inputHash()))!=1)bad();
        }
    }
    private Intent read(TaskPlanDraftJobs.Job j,Map<String,Object> row)throws Exception {
        metadata(j,row);var value=schema.read(str(row,"canonical_reference"));var c=schema.read(str(row,"config_json"));
        ProfessionalRuntimeObservations.closed(c,Set.of("revision","control_task_queue","professional_task_queue","activity_timeout_millis","heartbeat_timeout_millis"));
        var config=new TaskPlanDraftLaunchConfiguration(text(c,"revision"),text(c,"control_task_queue"),text(c,"professional_task_queue"),number(c,"activity_timeout_millis"),number(c,"heartbeat_timeout_millis"));
        var r=reference(value);if(!schema.canonical(r).equals(str(row,"canonical_reference"))||!schema.hash(r).equals(row.get("reference_sha256"))||!schema.canonical(config).equals(row.get("config_json"))||!schema.hash(config).equals(row.get("config_sha256")))bad();
        if(!j.tenant().equals(r.tenantId())||!j.project().equals(r.projectId())||!j.run().equals(r.runId())||!j.step().equals(r.stepId())||!j.task().equals(r.taskId())||!j.taskRevision().equals(r.taskRevision())||!j.inputHash().equals(r.inputSha256())||!schema.hash(schema.read(j.admissionJson())).equals(r.admissionSha256())||!r.inputArtifactId().equals(row.get("input_artifact_id"))||!r.inputReceiptSha256().equals(row.get("input_receipt_sha256"))||!r.admissionSha256().equals(row.get("job_admission_sha256"))||!config.controlTaskQueue().equals(r.controlTaskQueue())||!config.professionalTaskQueue().equals(r.professionalTaskQueue())||config.activityTimeoutMillis()!=r.activityTimeoutMillis()||config.heartbeatTimeoutMillis()!=r.heartbeatTimeoutMillis())bad();
        var intent=new Intent(j,str(row,"command_id"),r,str(row,"reference_sha256"),config,str(row,"config_sha256"));WireValues.uuid(intent.command);verifyJournal(j,row,"task.plan_draft.launch.prepared",intent.command,evidence(intent.command,intent.referenceHash,intent.configurationHash,r));return intent;
    }
    private void verifyAttempt(Intent intent,Map<String,Object> row){metadata(intent.job,row);if(!intent.command.equals(row.get("command_id"))||!intent.referenceHash.equals(row.get("reference_sha256")))bad();}
    private void verifyReceipt(Intent intent,JsonNode receipt,Map<String,Object> row)throws Exception{metadata(intent.job,row);if(!intent.referenceHash.equals(row.get("reference_sha256"))||!intent.reference.workflowId().equals(row.get("workflow_id"))||!text(receipt,"temporal_run_id").equals(row.get("temporal_run_id"))||!schema.canonical(receipt).equals(row.get("receipt_json"))||!schema.hash(receipt).equals(row.get("receipt_sha256")))bad();verifyJournal(intent.job,row,"task.plan_draft.launch.accepted",intent.command,receipt);if(one(db.query("SELECT COUNT(*) FROM system_job_run WHERE tenant_id=? AND run_id=? AND workflow_id=? AND job_type='PLAN_DRAFT' AND input_sha256=? AND started_at IS NOT NULL",(r,n)->r.getInt(1),intent.job.tenant(),intent.job.run(),intent.reference.workflowId(),intent.job.inputHash()))!=1)bad();}
    private com.fasterxml.jackson.databind.node.ObjectNode evidence(String command,String referenceHash,String configHash,PlanDraftProtocol.Reference reference){var n=(com.fasterxml.jackson.databind.node.ObjectNode)schema.tree(Map.of("schema_version","1.0.0","job_type","PLAN_DRAFT","command_id",command,"reference_sha256",referenceHash,"config_sha256",configHash));n.set("reference",schema.tree(reference));return n;}
    static PlanDraftProtocol.Reference reference(JsonNode n){ProfessionalRuntimeObservations.closed(n,Set.of("schema_version","execution_kind","job_type","node_kind","tenant_id","project_id","run_id","step_id","task_id","task_revision","input_artifact_id","input_sha256","input_receipt_sha256","admission_sha256","policy_revision","control_task_queue","professional_task_queue","activity_timeout_millis","heartbeat_timeout_millis"));return new PlanDraftProtocol.Reference(text(n,"schema_version"),text(n,"execution_kind"),text(n,"job_type"),text(n,"node_kind"),text(n,"tenant_id"),text(n,"project_id"),text(n,"run_id"),text(n,"step_id"),text(n,"task_id"),text(n,"task_revision"),text(n,"input_artifact_id"),text(n,"input_sha256"),text(n,"input_receipt_sha256"),text(n,"admission_sha256"),text(n,"policy_revision"),text(n,"control_task_queue"),text(n,"professional_task_queue"),number(n,"activity_timeout_millis"),number(n,"heartbeat_timeout_millis"));}
    private void metadata(TaskPlanDraftJobs.Job j,Map<String,Object> row){if(!TransactionSynchronizationManager.isActualTransactionActive()||!j.tenant().equals(TenantScope.requireCurrent().tenantId())||!j.actor().equals(TenantScope.requireCurrent().subjectId()))deny();for(var e:Map.of("tenant_id",j.tenant(),"project_id",j.project(),"run_id",j.run(),"created_by",j.actor(),"classification",j.classification(),"schema_version","1.0.0","schema_manifest_sha256",schema.manifest()).entrySet())if(!e.getValue().equals(row.get(e.getKey())))bad();}
    private void journal(TaskPlanDraftJobs.Job j,String audit,String event,String action,String target,JsonNode evidence,java.time.LocalDateTime now)throws Exception{changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenant(),j.project(),audit,j.actor(),action,schema.canonical(evidence),target,j.run(),schema.manifest(),j.actor(),now,j.classification()));changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,?,?,?)",j.tenant(),event,j.run(),action,schema.canonical(evidence),now));}
    private void verifyJournal(TaskPlanDraftJobs.Job j,Map<String,Object> row,String action,String target,JsonNode evidence)throws Exception{if(!schema.canonical(evidence).equals(one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND created_by=? AND action=? AND request_id=? AND trace_id=? AND result='SUCCESS' AND schema_manifest_sha256=? LIMIT 2",(r,n)->r.getString(1),j.tenant(),j.project(),str(row,"audit_id"),j.actor(),j.actor(),action,target,j.run(),schema.manifest())))||!schema.canonical(evidence).equals(one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type=? AND aggregate_revision=1 LIMIT 2",(r,n)->r.getString(1),j.tenant(),str(row,"event_id"),j.run(),action))))bad();}
    private java.time.LocalDateTime now(){return one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static long number(JsonNode n,String k){if(!n.required(k).isIntegralNumber()||!n.required(k).canConvertToLong())bad();return n.required(k).longValue();}private static String str(Map<String,Object> row,String k){if(!(row.get(k) instanceof String))bad();return (String)row.get(k);}private static <T>T one(List<T> rows){if(rows.size()!=1||rows.get(0)==null)bad();return rows.get(0);}private static void changed(int count){if(count!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
